    /** Whale trades this event announces. One event is minted per stored whale trade, so this is 1. */
    count: number;
    /** The raw whale_alerts.id of the trade, the same number as sequence. GET /api/v1/whale-trades/{id} accepts it and returns the trade with its wallet, grade, size, price and market. */
    whale_alert_id: number;
    /** The Polymarket condition id of the market the trade was in. */
    condition_id: string;
    /** 0xinsider's numeric id for the wallet's trader row. It is not the trd_ id, which is derived from the address; read the address and grade from the whale trade. */
