export type ResponseMeta = {
  /** Unique request ID (req_ prefix). The same value as the X-Request-Id response header, the request's usage accounting row and its log lines. */
  request_id: string;
  cached: boolean;
  /** Cache age in seconds. Omitted when the response was not cached, and also when it was cached but its age cannot be established (an entry stored before its cache carried a computed instant). Never a placeholder: an unknown age is reported as no value rather than as the cache TTL. */
  cache_age_s?: number;
  /** Advisory request weight (relative compute cost). 1 for simple reads; higher for heavier endpoints. Not a credit/price. */
  cost: number;
  /** Committed PostgreSQL-owned leaderboard generation for the returned rows and cursor. Present on GET /api/v1/leaderboard; omitted on endpoints that do not read this ranking. */
  ranking_generation?: number;
  /** Authoritative RFC3339 timestamp from cache_generations.updated_at for ranking_generation. It is read in the same repeatable-read snapshot as the leaderboard rows and is not request time, cache write time, or row insertion order. */
  ranking_as_of?: string;
  /** Which path produced the team-directional read on this response. Only present on endpoints that compute one (today: GET /api/v1/sports-edge-signals). "live" means the read RAN. "degraded" means it FAILED, so nothing was measured and the ranking fell back to raw conviction. The flag describes the READ, not its consequence: a read that ran and found nothing groupable also leaves the directional fields null, and that is honestly "live" -- the per-signal nulls already say "nothing to enrich here", so this snapshot-level flag carries only what they cannot, namely whether the read ran at all. A degraded response is cached on the shorter degraded TTL so it self-heals. Reported SEPARATELY from ranking_source because the two degradations are independent -- a smart-money DB miss weakens the ranking DATA, a directional failure removes a ranking WEIGHT -- and a consumer down-weighting a degraded response needs to know which input it lost. Omitted on endpoints that compute no directional read. */
  directional_source?: "live" | "degraded";
  /** Which ranking-data path produced this response. Only present on endpoints that can degrade a ranking (today: GET /api/v1/sports-edge-signals). "live" is the normal path (the current holder pile from the provider batch); "db_only" is the degraded fallback (a truthful but weaker trader_markets ranking) served when the live sharp-money ranking batch is unavailable (a smart-money DB read failure, not a Polymarket outage) and cached on a shorter TTL, so a consumer can down-weight or skip it. Omitted on endpoints that never degrade. */
  ranking_source?: "live" | "db_only";
  /** Whole filtered snapshot category-evidence status before pagination. Operational live always remains partial source coverage. */
  category_skill_source?: "live" | "partial" | "degraded" | "unavailable";
  category_skill_model_version?: string;
  category_skill_taxonomy_version?: string;
  category_skill_platform?: "polymarket";
  category_skill_scope?: "observed_goldsky_primary_taker_fill";
  category_skill_source_coverage?: "partial_whale_threshold_fills" | "graded_wallet_fills";
  category_skill_observation_started_at?: string;
  /** Whole-model operational readiness captured with the category model snapshot. Present on category-enriched responses even when the filtered signal list is empty. When true, category_skill_source is degraded and sports-edge-signals uses the shorter degraded cache TTL. */
  category_skill_model_operationally_degraded?: boolean;
  category_skill_status_counts?: {
    live: number;
    insufficient: number;
    stale: number;
    unknown: number;
    degraded: number;
  };
  /** SHA-256 of the funded signal membership/order/rank/cursor vector immediately before category-skill enrichment. Sports-edge-signals only. */
  category_skill_base_payload_hash?: string;
  /** Independent SHA-256 recomputation over the same base fields immediately after category-skill enrichment. Equality with category_skill_base_payload_hash proves shadow enrichment did not change funded inputs. Sports-edge-signals only. */
  category_skill_enriched_base_payload_hash?: string;
};

/** One same-day pick that is selected but not yet released: its stable slot rank plus the backend-owned release and kickoff instants. Deliberately minimal -- no matchup, category, platform, side, price, or holder fields exist on this shape before release. */
export type ScheduledPickSlot = {
  /** Stable 1-based slot within the product day's ranked picks. The slot keeps this rank when it releases. */
  pick_rank: number;
  /** The slot's scheduled release instant, normally the current provider kickoff minus one hour. The actual publish can trail it by bounded worker delay. */
  release_at: string;
  /** The backed game's current kickoff instant. */
  kickoff: string;
};

/** One side's score in a single set. The verbatim provider text stays on the team's `score` string; this is the parsed form. */
export type ScoreCell = {
  /** Games won in this set. */
  games: number;
  /** Tiebreak points won in this set. Omitted when the set had no tiebreak; absence and zero are different. */
  tiebreak?: number;
};

/** Shape the provider score string was parsed into. `two_side` is one aggregate per side (basketball `105-98`), `multi_set` is per-set columns (tennis `6-7(5-7), 6-0, 1-0`), `esports_series` is a maps/sets/format triplet (`000-000|2-0|Bo3`). Omitted when the score could not be parsed. */
export type ScoreFormat = "two_side" | "multi_set" | "esports_series";

